        TalentPoolDetailData.TalentPoolDetail(
            no = talentPool.no,
            memberNo = talentPool.no, // 예시로 no와 memberNo를 같게 설정
            location = talentPool.location,
            instrument = talentPool.instrument, // 첫 번째 해시태그를 악기로 사용, 없을 경우 "기타"
            experience = talentPool.experience,
            days = mutableListOf("월","화", "수", "목", "금", "토", "일").shuffled().take(3)
                .toMutableList(), // 예시로 랜덤하게 2개의 요일 선택
            hashTags = talentPool.hashTagList,
            mediaUrl = "https://example.com/media/${talentPool.no}", // 예시 미디어 URL
            introduce = talentPool.content,
            chatUrl = "https://example.com/chat/${talentPool.no}" // 예시 채팅 URL
        )
    }

    return testTalentPoolDetailList
}